-- Extend the private document bucket and ownership policies to PowerPoint.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table public.topictrail_cloud_documents in access exclusive mode;
create temporary table topictrail_pptx_original_guard on commit drop as
 select count(*) as n,md5(coalesce(string_agg(md5(to_jsonb(d)::text),'' order by user_id,id),'')) as digest from public.topictrail_cloud_documents d;
do $guard$ begin
 if current_user<>'postgres' or current_database()<>'postgres' then raise exception 'Unexpected target'; end if;
 perform 1 from storage.buckets where id='topictrail-documents' for update;
 if (select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.topictrail_cloud_documents'::regclass and conname='topictrail_cloud_documents_format_check') is distinct from 'CHECK ((format = ANY (ARRAY[''pdf''::text, ''docx''::text])))' then raise exception 'Format constraint drift'; end if;
 if (select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where (schemaname='public' and tablename='topictrail_cloud_documents') or (schemaname='storage' and policyname like 'topictrail_cloud_%')) is distinct from '[{"cmd":"INSERT","permissive":"PERMISSIVE","policyname":"topictrail_cloud_documents_insert","qual":null,"roles":["authenticated"],"schemaname":"public","tablename":"topictrail_cloud_documents","with_check":"((user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1\n   FROM storage.objects o\n  WHERE ((o.bucket_id = ''topictrail-documents''::text) AND (o.name = (((((topictrail_cloud_documents.user_id)::text || ''/''::text) || topictrail_cloud_documents.id) || ''.''::text) || topictrail_cloud_documents.format)) AND (o.owner_id = (( SELECT auth.uid() AS uid))::text) AND ((o.metadata ->> ''size''::text) = (topictrail_cloud_documents.byte_size)::text) AND ((o.metadata ->> ''mimetype''::text) =\n        CASE topictrail_cloud_documents.format\n            WHEN ''pdf''::text THEN ''application/pdf''::text\n            ELSE ''application/vnd.openxmlformats-officedocument.wordprocessingml.document''::text\n        END)))))"},{"cmd":"SELECT","permissive":"PERMISSIVE","policyname":"topictrail_cloud_documents_select","qual":"(user_id = ( SELECT auth.uid() AS uid))","roles":["authenticated"],"schemaname":"public","tablename":"topictrail_cloud_documents","with_check":null},{"cmd":"DELETE","permissive":"RESTRICTIVE","policyname":"topictrail_cloud_guard_delete","qual":"(bucket_id <> ''topictrail-documents''::text)","roles":["public"],"schemaname":"storage","tablename":"objects","with_check":null},{"cmd":"INSERT","permissive":"RESTRICTIVE","policyname":"topictrail_cloud_guard_insert","qual":null,"roles":["public"],"schemaname":"storage","tablename":"objects","with_check":"((bucket_id <> ''topictrail-documents''::text) OR ((owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ ((''^''::text || (( SELECT auth.uid() AS uid))::text) || ''/[a-z0-9][a-z0-9-]{0,127}\\.(pdf|docx)$''::text))))"},{"cmd":"SELECT","permissive":"RESTRICTIVE","policyname":"topictrail_cloud_guard_select","qual":"((bucket_id <> ''topictrail-documents''::text) OR ((owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ ((''^''::text || (( SELECT auth.uid() AS uid))::text) || ''/[a-z0-9][a-z0-9-]{0,127}\\.(pdf|docx)$''::text))))","roles":["public"],"schemaname":"storage","tablename":"objects","with_check":null},{"cmd":"UPDATE","permissive":"RESTRICTIVE","policyname":"topictrail_cloud_guard_update","qual":"(bucket_id <> ''topictrail-documents''::text)","roles":["public"],"schemaname":"storage","tablename":"objects","with_check":"(bucket_id <> ''topictrail-documents''::text)"},{"cmd":"INSERT","permissive":"PERMISSIVE","policyname":"topictrail_cloud_objects_insert","qual":null,"roles":["authenticated"],"schemaname":"storage","tablename":"objects","with_check":"((bucket_id = ''topictrail-documents''::text) AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ ((''^''::text || (( SELECT auth.uid() AS uid))::text) || ''/[a-z0-9][a-z0-9-]{0,127}\\.(pdf|docx)$''::text)))"},{"cmd":"SELECT","permissive":"PERMISSIVE","policyname":"topictrail_cloud_objects_select","qual":"((bucket_id = ''topictrail-documents''::text) AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ ((''^''::text || (( SELECT auth.uid() AS uid))::text) || ''/[a-z0-9][a-z0-9-]{0,127}\\.(pdf|docx)$''::text)))","roles":["authenticated"],"schemaname":"storage","tablename":"objects","with_check":null}]'::jsonb then raise exception 'Policy drift'; end if;
 if not exists(select 1 from storage.buckets where id='topictrail-documents' and not public and file_size_limit=52428800 and allowed_mime_types=array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document']::text[]) then raise exception 'Bucket configuration drift or already extended'; end if;
end $guard$;
alter table public.topictrail_cloud_documents drop constraint topictrail_cloud_documents_format_check;
alter table public.topictrail_cloud_documents add constraint topictrail_cloud_documents_format_check check(format in ('pdf','docx','pptx'));
alter policy topictrail_cloud_documents_insert on public.topictrail_cloud_documents with check (((user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM storage.objects o
  WHERE ((o.bucket_id = 'topictrail-documents'::text) AND (o.name = (((((topictrail_cloud_documents.user_id)::text || '/'::text) || topictrail_cloud_documents.id) || '.'::text) || topictrail_cloud_documents.format)) AND (o.owner_id = (( SELECT auth.uid() AS uid))::text) AND ((o.metadata ->> 'size'::text) = (topictrail_cloud_documents.byte_size)::text) AND ((o.metadata ->> 'mimetype'::text) =
        CASE topictrail_cloud_documents.format
            WHEN 'pdf'::text THEN 'application/pdf'::text
            WHEN 'docx'::text THEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'::text
            WHEN 'pptx'::text THEN 'application/vnd.openxmlformats-officedocument.presentationml.presentation'::text
            ELSE NULL::text
        END))))));
alter policy topictrail_cloud_guard_insert on storage.objects with check (((bucket_id <> 'topictrail-documents'::text) OR ((owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ (('^'::text || (( SELECT auth.uid() AS uid))::text) || '/[a-z0-9][a-z0-9-]{0,127}\.(pdf|docx|pptx)$'::text)))));
alter policy topictrail_cloud_guard_select on storage.objects using (((bucket_id <> 'topictrail-documents'::text) OR ((owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ (('^'::text || (( SELECT auth.uid() AS uid))::text) || '/[a-z0-9][a-z0-9-]{0,127}\.(pdf|docx|pptx)$'::text)))));
alter policy topictrail_cloud_objects_insert on storage.objects with check (((bucket_id = 'topictrail-documents'::text) AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ (('^'::text || (( SELECT auth.uid() AS uid))::text) || '/[a-z0-9][a-z0-9-]{0,127}\.(pdf|docx|pptx)$'::text))));
alter policy topictrail_cloud_objects_select on storage.objects using (((bucket_id = 'topictrail-documents'::text) AND (owner_id = (( SELECT auth.uid() AS uid))::text) AND (name ~ (('^'::text || (( SELECT auth.uid() AS uid))::text) || '/[a-z0-9][a-z0-9-]{0,127}\.(pdf|docx|pptx)$'::text))));
-- Bucket configuration only; never modify Storage object rows or bytes.
update storage.buckets set allowed_mime_types=array_append(allowed_mime_types,'application/vnd.openxmlformats-officedocument.presentationml.presentation') where id='topictrail-documents';
do $guard$ begin
 if not exists(select 1 from topictrail_pptx_original_guard g where g.n=(select count(*) from public.topictrail_cloud_documents) and g.digest=(select md5(coalesce(string_agg(md5(to_jsonb(d)::text),'' order by user_id,id),'')) from public.topictrail_cloud_documents d)) then raise exception 'Original metadata changed'; end if;
end $guard$;
notify pgrst,'reload schema';
commit;
